using namespace survey;
struct MemoryStore:Store {
  std::map<unsigned,std::string> records;bool ready=true,fail=false,uncertain=false;
  bool initialize() override{return ready;}
  bool read(unsigned n,std::string &s,bool &exists) override {exists=records.count(n);if(exists)s=records[n];return exists||records.empty()||n>records.rbegin()->first;}
  bool commit(unsigned n,const std::string &s) override {if(fail||records.count(n))return false;records[n]=s;return !uncertain;}
};
struct ReceiverMock:Receiver {bool available=true;unsigned calls=0;BaseRequest last;bool apply(const BaseRequest &r) override {++calls;last=r;return available;}};
std::string id(unsigned n){char out[33];std::snprintf(out,sizeof(out),"%032x",n);return out;}
std::string encode(JsonDocument &d){return precise_json(d.as<JsonVariantConst>());}
DynamicJsonDocument decode(const std::string &s){DynamicJsonDocument d(32768);assert(!deserializeJson(d,s));return d;}
const char *fixture=R"({"crs":"wgs84_utm","frame":"WGS84","epoch":2026.7,"reference_confirmed":true,"zone":14,"south":false,"units":"m","vertical":"ellipsoid","rover_model":"Test reference","rover_height":2,"rover_offset":0,"rover_radius":0,"rover_method":"vertical","base_model":"Test reference","base_height":1.5,"base_offset":0,"base_radius":0,"base_method":"vertical","antenna_confirmed":true,"base_name":"Test control","station":7,"base_mode":"known","base_lat":19.4,"base_lon":-99.1,"base_ground_h":2200,"base_tolerance":0.02,"duration":2,"min_samples":3,"h_limit":0.03,"v_limit":0.05,"correction_limit":3000})";
struct Rig {
  MemoryStore store;ReceiverMock receiver;Engine engine;Fix fix;unsigned next=10;std::string job=id(1);
  Rig():engine(store,receiver){fix.now=fix.received=10000;fix.epoch=1473000000000ULL;fix.rover=fix.profile_ok=fix.position_valid=fix.fixed=fix.linked=fix.reference_valid=true;fix.position={19.4001,-99.1001,2204};fix.reference=ecef({19.4,-99.1,2201.5});fix.station=7;fix.hacc=.01;fix.vacc=.02;fix.satellites=30;std::strcpy(fix.utc,"2026-09-10T12:00:00Z");engine.recover();}
  DynamicJsonDocument state(){return decode(engine.snapshot(fix));}
  std::string command(const char *op,unsigned n=0){DynamicJsonDocument d(16384);d["id"]=id(n?n:next++);d["op"]=op;d["job"]=job;d["revision"]=1;d["name"]="Bench fixture";d["point_id"]="1001";d["code"]="BM";d["description"]="Test observation";d["confirm"]=true;return encode(d);}
  void send(const std::string &s){engine.command(s.c_str(),fix);}
  void setup(){send(command("job.create",1));auto d=decode(command("job.configure",2));d["revision"]=0;auto c=decode(fixture);d["config"]=c.as<JsonVariantConst>();send(encode(d));assert(state()["jobs"][0]["revision"]==1);}
  void advance(unsigned ms=1000){fix.now+=ms;fix.received=fix.now;fix.epoch+=ms;engine.tick(fix);}
};
std::string target_command(Rig &r,const char *name="CP1"){
  auto d=decode(r.command("target.create"));auto t=d.createNestedObject("target");t["id"]=name;t["kind"]="control";t["source"]="Independent test control certificate";t["reference_confirmed"]=true;t["independent_source"]=true;
  double e,n;assert(utm(r.fix.position,14,false,e,n));t["easting"]=e;t["northing"]=n;t["height"]=2202.;auto c=decode(fixture);auto ref=t.createNestedObject("reference");for(const char *key:{"crs","frame","epoch","zone","south","units","vertical"})ref[key]=c[key];return encode(d);
}
std::string line_command(Rig &r,const char *point,const char *line,const char *action,const char *previous=""){
  auto d=decode(r.command("collect.start"));d["point_id"]=point;auto l=d.createNestedObject("line");l["id"]=line;l["action"]=action;l["previous_point"]=previous;return encode(d);
}
DynamicJsonDocument line_list(Rig &r){return decode(r.engine.read(("{\"view\":\"lines\",\"offset\":0,\"job\":\""+r.job+"\"}").c_str(),r.fix));}
void line_tests(){
  {Rig r;r.setup();auto first=line_command(r,"V1","L1","start");r.send(first);r.advance();r.advance();r.engine.recover();r.send(first);assert(line_list(r)["lines"][0]["vertices"]==1&&line_list(r)["lines"][0]["state"]=="open");
    r.send(line_command(r,"V2","L1","continue","old"));assert(r.state()["operation"]["state"]=="rejected");auto wrong=decode(line_command(r,"V2","L1","continue","V1"));wrong["code"]="OTHER";r.send(encode(wrong));assert(r.state()["operation"]["state"]=="rejected");
    r.send(line_command(r,"V2","L1","continue","V1"));r.advance();r.advance();r.send(line_command(r,"V3","L1","end","V2"));r.advance();r.advance();r.engine.recover();auto list=line_list(r);assert(list["lines"][0]["state"]=="closed"&&list["lines"][0]["vertices"]==3);assert(r.state()["last_point"]["line_previous"]=="V2");
    r.send(line_command(r,"V4","L1","start"));assert(r.state()["operation"]["state"]=="rejected");r.send(line_command(r,"V4","L1","continue","V3"));assert(r.state()["operation"]["state"]=="rejected");}
  for(const char *failure:{"quality","cancel","restart","delete","code","setup"}){
    Rig r;r.setup();r.send(line_command(r,"V1","L1","start"));r.advance();r.advance();
    if(std::strcmp(failure,"delete")==0||std::strcmp(failure,"code")==0){auto edit=decode(r.command("point.edit"));edit["point_id"]="V1";edit["note"]="";edit["reason"]="Line vertex audit";edit["deleted"]=std::strcmp(failure,"delete")==0;if(std::strcmp(failure,"code")==0)edit["code"]="EDITED";r.send(encode(edit));edit["id"]=id(100);edit["revision"]=2;edit["deleted"]=false;edit["code"]="BM";r.send(encode(edit));}
    else if(std::strcmp(failure,"setup")==0){auto config=decode(r.command("job.configure"));config["config"]=decode(fixture).as<JsonVariantConst>();r.send(encode(config));}
    else {r.send(line_command(r,"V2","L1","continue","V1"));if(std::strcmp(failure,"quality")==0){r.fix.fixed=false;r.advance();r.fix.fixed=true;}else if(std::strcmp(failure,"cancel")==0)r.send(r.command("collect.cancel"));}
    r.engine.recover();assert(line_list(r)["lines"][0]["state"]=="broken");assert(line_list(r)["lines"][0]["vertices"]==1);r.send(line_command(r,"V2","L1","continue","V1"));assert(r.state()["operation"]["state"]=="rejected");
  }
  {Rig r;r.setup();r.send(line_command(r,"V1","L1","start"));r.advance();r.advance();r.fix.reference.x+=.005;r.send(line_command(r,"V2","L1","continue","V1"));assert(r.state()["operation"]["state"]=="rejected");assert(r.state()["operation"]["message"].as<std::string>().find("Base reference changed")!=std::string::npos);}
  {Rig r;r.setup();r.send(line_command(r,"V1","L1","start"));r.advance();r.advance();auto next=line_command(r,"V2","L1","continue","V1");r.send(next);r.advance();r.store.uncertain=true;r.advance();r.store.uncertain=false;r.engine.recover();r.send(next);assert(r.state()["operation"]["state"]=="completed"&&line_list(r)["lines"][0]["vertices"]==2);}
  {Rig r;r.setup();for(unsigned i=0;i<64;++i){auto key=std::to_string(i);r.send(line_command(r,key.c_str(),key.c_str(),"start"));r.advance();r.advance();}assert(r.state()["lines_used"]==64);r.send(line_command(r,"OVER","OVER","start"));assert(r.state()["operation"]["state"]=="rejected");auto list=line_list(r);assert(list["total"]==64&&list["lines"].size()==25&&list["next"]==25);}
  std::cout<<"PASS: line continuity, immutable vertices, gaps, deletion/code/setup breaks, restart, reference changes, uncertain writes and limits\n";
}
