int main(int argc,char **argv){
  if(argc>1&&std::string(argv[1])=="--utm"){std::cout.precision(15);for(int zone:{1,14,31,60})for(double lat:{-80.,-33.,0.,19.4,60.,84.})for(double delta:{-3.,-.1,0.,3.}){double lon=zone*6-183+delta,e,n;assert(utm({lat,lon,0},zone,lat<0,e,n));std::cout<<zone<<","<<lat<<","<<lon<<","<<e<<","<<n<<"\n";}return 0;}
  if(argc>1&&std::string(argv[1])=="--serve") {Rig r;std::string line;while(std::getline(std::cin,line)){auto d=decode(line);if(d["query"].is<JsonObject>()){std::string q;serializeJson(d["query"],q);std::cout<<r.engine.read(q.c_str(),r.fix)<<std::endl;continue;}if(d["restart"]==true)r.engine.recover();if(d["fix"].is<JsonObject>()){auto f=d["fix"];if(f.containsKey("fixed"))r.fix.fixed=f["fixed"];if(f.containsKey("rover"))r.fix.rover=f["rover"];if(f.containsKey("station"))r.fix.station=f["station"];}
    if(d["command"].is<JsonObject>()){std::string c=precise_json(d["command"]);r.send(c);}if(d["advance"].is<unsigned>())r.advance(d["advance"]);std::cout<<r.engine.snapshot(r.fix)<<std::endl;}return 0;}
  assert(argc==2);tests(argv[1]);
}
